with cleaned as (select id, store_id, order_date, status, amount, discount, shipping_fee, length(status) as status_length, case when discount >= 0.35 then 'High' when discount >= 0.08 then 'Medium' else 'Low' end as discount_tier from orders where customer_id is not null) select id, store_id, status, amount, discount, status_length, discount_tier, last_value(shipping_fee, true) over (partition by status, store_id order by amount, id rows between unbounded preceding and current row) as last_known_shipping_fee, sum(shipping_fee) over (partition by status order by discount, id rows between unbounded preceding and current row) as running_shipping_fee, avg(shipping_fee) over (partition by store_id, status order by status_length, id rows between 5 preceding and 1 preceding) as shipping_fee_avg_5_prior from cleaned;
